INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('40', '6', '5', '5', 'calculation', '12', '设连续可微函数 \(z=z(x,y)\) 由 \(F(xz-y,x-yz)=0\) 唯一确定，\(L\) 为正向单位圆周，求
\[I=\oint_L(xz^2+2yz)\,\mathrm dy-(2xz+yz^2)\,\mathrm dx.\]', '\(I=2\pi\)。', '令 \(Q=xz^2+2yz\)、\(P=-(2xz+yz^2)\)。由隐式方程分别求导，可化出
\[(xz+y)z_x+(x+yz)z_y=1-z^2.\]
使用 Green 公式，\(Q_x-P_y=2[(xz+y)z_x+(x+yz)z_y+z^2]=2\)，故
\[I=2\iint_{x^2+y^2\le1}\mathrm dx\,\mathrm dy=2\pi.\]', '2012 年第三届全国大学生数学竞赛决赛（非数学专业） 设连续可微函数 (z=z(x,y) ) 由 (F(xz-y,x-yz)=0 ) 唯一确定， (L ) 为正向单位圆周，求 [I= L(xz 2+2yz) , dy-(2xz+yz 2) , dx. ] (I=2 )。 令 (Q=xz 2+2yz )、 (P=-(2xz+yz 2) )。由隐式方程分别求导，可化出 [(xz+y)z x+(x+yz)z y=1-z 2. ] 使用 Green 公式， (Q x-P y=2[(xz+y)z x+(x+yz)z y+z 2]=2 )，故 [I=2 x 2+y 2 1 dx , dy=2 . ]', '2', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('41', '6', '6', '6', 'comprehensive', '16', '1. 解初值问题 \(y''-xy=xe^{x^2},\ y(0)=1\)。
2. 若 \(y=f(x)\) 为其解，证明 \(\lim_{n\to\infty}\int_0^1\frac{nf(x)}{n^2x^2+1}\,\mathrm dx=\pi/2\)。', '1. \(y=e^{x^2}\)。 2. 极限为 \(\pi/2\)。', '1. 线性方程积分因子为 \(e^{-x^2/2}\)，代入初值得 \(y=e^{x^2}\)。
2. 分解 \(e^{x^2}=1+(e^{x^2}-1)\)。第一项积分为 \(\arctan n\to\pi/2\)。对第二项，在 \([0,\delta]\) 用 \(e^{x^2}-1\to0\) 控制，在 \([\delta,1]\) 用分母的 \(n^2x^2\) 控制，故该项趋于 0。', '2012 年第三届全国大学生数学竞赛决赛（非数学专业） 1. 解初值问题 (y''-xy=xe x 2 , y(0)=1 )。 2. 若 (y=f(x) ) 为其解，证明 ( n 0 1 nf(x) n 2x 2+1 , dx= /2 )。 1. (y=e x 2 )。 2. 极限为 ( /2 )。 1. 线性方程积分因子为 (e -x 2/2 )，代入初值得 (y=e x 2 )。 2. 分解 (e x 2 =1+(e x 2 -1) )。第一项积分为 ( n /2 )。对第二项，在 ([0, ] ) 用 (e x 2 -1 0 ) 控制，在 ([ ,1] ) 用分母的 (n 2x 2 ) 控制，故该项趋于 0。', '2', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('44', '7', '3', '3', 'calculation', '10', '求方程 \(x^2\sin(1/x)=2x-501\) 的近似解，精确到 \(0.001\)。', '\(x\approx501.000\)。', '由 Taylor 公式 \(\sin(1/x)=1/x-\sin(\theta/x)/(2x^2)\)，方程化为 \(x=501-\frac12\sin(\theta/x)\)。可知 \(x>500\)，故 \(|x-501|<1/(2x)<0.001\)。', '2012 年第四届全国大学生数学竞赛初赛（非数学类） 求方程 (x 2 (1/x)=2x-501 ) 的近似解，精确到 (0.001 )。 (x 501.000 )。 由 Taylor 公式 ( (1/x)=1/x- ( /x)/(2x 2) )，方程化为 (x=501- 12 ( /x) )。可知 (x>500 )，故 (|x-501|<1/(2x)<0.001 )。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('45', '7', '4', '4', 'calculation', '12', '设 \(y=f(x)\) 二阶可导，\(f''''(x)>0\)、\(f(0)=f''(0)=0\)。曲线在 \(P(x,f(x))\) 处切线与 \(x\) 轴交于截距 \(u\)，求
\[\lim_{x\to0}\frac{x^3f(u)}{f(x)\sin^3u}.\]', '\(2\)。', '切线方程给出 \(u=x-f(x)/f''(x)\)。二阶展开得 \(f(x)=\frac12f''''(0)x^2+o(x^2)\)，从而 \(u/x\to1/2\)、\(f(u)/u^2\to f''''(0)/2\)、\(\sin u/u\to1\)。代入即得极限 2。', '2012 年第四届全国大学生数学竞赛初赛（非数学类） 设 (y=f(x) ) 二阶可导， (f''''(x)>0 )、 (f(0)=f''(0)=0 )。曲线在 (P(x,f(x)) ) 处切线与 (x ) 轴交于截距 (u )，求 [ x 0 x 3f(u) f(x) 3u . ] (2 )。 切线方程给出 (u=x-f(x)/f''(x) )。二阶展开得 (f(x)= 12f''''(0)x 2+o(x 2) )，从而 (u/x 1/2 )、 (f(u)/u 2 f''''(0)/2 )、 ( u/u 1 )。代入即得极限 2。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('46', '7', '5', '5', 'proof', '12', '求最小实数 \(C\)，使任意满足 \(\int_0^1|f(x)|\,\mathrm dx=1\) 的连续函数均有
\[\int_0^1f(\sqrt x)\,\mathrm dx\le C.\]', '最小值 \(C=2\)。', '令 \(x=t^2\)，则左端为 \(2\int_0^1t f(t)\,\mathrm dt\le2\int_0^1|f(t)|\,\mathrm dt=2\)。取 \(f_n(x)=(n+1)x^n\)，其绝对值积分为 1，而目标积分为 \(2(n+1)/(n+2)\to2\)，故最小上界正是 2。', '2012 年第四届全国大学生数学竞赛初赛（非数学类） 求最小实数 (C )，使任意满足 ( 0 1|f(x)| , dx=1 ) 的连续函数均有 [ 0 1f( x) , dx C. ] 最小值 (C=2 )。 令 (x=t 2 )，则左端为 (2 0 1t f(t) , dt 2 0 1|f(t)| , dt=2 )。取 (f n(x)=(n+1)x n )，其绝对值积分为 1，而目标积分为 (2(n+1)/(n+2) 2 )，故最小上界正是 2。', '1', 'published') ON CONFLICT (id) DO NOTHING;